function parseArgs(argv: string[]): CliArgs {
  const args: CliArgs = { task: undefined as unknown as string, startUrl: undefined as unknown as string };
  const positional: string[] = [];
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    switch (arg) {
      case "--format":
        args.format = argv[++i] as CliArgs["format"];
        break;
      case "--max-chars":
        args.maxChars = Number(argv[++i]);
        break;
      case "--max-steps":
        args.maxSteps = Number(argv[++i]);
        break;
      case "--max-seconds":
        args.maxSeconds = Number(argv[++i]);
        break;
      case "--no-typing":
        args.allowTyping = false;
        break;
      case "--screenshot":
        args.screenshotPath = argv[++i];
        break;
      case "--no-screenshot":
        args.screenshot = "none";
        break;
      case "--record":
        args.recordPath = argv[++i];
        break;
      case "--help":
      case "-h":
        args.help = true;
        break;
      default:
        positional.push(arg);
    }
  }
  const [task, startUrl] = positional;
  return { ...args, task, startUrl };
}

export async function runCli(argv: string[]): Promise<number> {
  const args = parseArgs(argv);
  if (args.help || !args.task || !args.startUrl) {
    console.log(HELP);
    return args.help ? 0 : 1;
  }

  const { screenshotPath, recordPath, ...navigateArgs } = args;
  let recordDir: string | undefined;
  let tempRecordDir: string | undefined;
  if (recordPath) {
    if (recordPath.endsWith(".webm")) {
      // Scratch space lives under the OS temp directory, never the caller's
      // working directory, and is removed after the video is copied out.
      const os = await import("node:os");
      const fs = await import("node:fs/promises");
      tempRecordDir = await fs.mkdtemp(join(os.tmpdir(), "jev-browser-record-"));
      recordDir = tempRecordDir;
    } else {
      recordDir = recordPath;
    }
  }
  try {
    const result = (await navigate({
      ...navigateArgs,
      screenshot: screenshotPath ? "final" : (args.screenshot ?? "final"),
      recordDir,
    })) as Record<string, any>;
    if (recordPath?.endsWith(".webm") && result.video_path) {
      const fs = await import("node:fs/promises");
      // Playwright can flush the video for a moment after close; wait for the
      // source file to settle before copying, or the copy truncates.
      let size = -1;
      for (let i = 0; i < 20; i++) {
        const stat = await fs.stat(result.video_path).catch(() => null);
        const current = stat?.size ?? -1;
        if (current === size && current > 0) break;
        size = current;
        await new Promise((r) => setTimeout(r, 500));
      }
      await fs.copyFile(result.video_path, recordPath);
      result.video_path = recordPath;
    }

    if (screenshotPath && result.screenshot_base64_jpeg) {
      await mkdir(dirname(screenshotPath), { recursive: true });
      await writeFile(screenshotPath, Buffer.from(result.screenshot_base64_jpeg, "base64"));
      result.screenshot_path = screenshotPath;
    }
    // The CLI prints JSON; base64 screenshots belong in files, not terminals.
    delete result.screenshot_base64_jpeg;

    console.log(JSON.stringify(result, null, 2));
    return result.status === "error" ? 1 : 0;
  } finally {
    if (tempRecordDir) {
      const fs = await import("node:fs/promises");
      await fs.rm(tempRecordDir, { recursive: true, force: true }).catch(() => {});
    }
  }
}

export function isNoiseName(name: string): boolean {
  const lowered = name.trim().toLowerCase();
  if (lowered.length === 0 || lowered.length > 80) return true;
  if (JUNK_NAMES.has(lowered)) return true;
  if (/^[\d\s.,:;()[\]-]+$/.test(lowered)) return true; // citation numbers, lone brackets
  return false;
}

export function isNoiseHref(href: string): boolean {
  if (!href) return false; // buttons and inputs legitimately have no href
  if (href.startsWith("#")) return true;
  if (href.startsWith("javascript:")) return true;
  if (href.startsWith("mailto:") || href.startsWith("tel:")) return true;
  if (href.includes("action=edit")) return true;
  return false;
}

export function buildActionSpace(raw: RawElement[]): { elements: PageElement[]; truncated: boolean } {
  const seenHrefs = new Set<string>();
  const elements: PageElement[] = [];
  for (const el of raw) {
    if (elements.length >= MAX_ELEMENTS) break;
    if (isNoiseName(el.text)) continue;
    if (isNoiseHref(el.href)) continue;
    // Never offer to type into password or file inputs.
    if (el.typeable && (el.typeAttr === "password" || el.typeAttr === "file")) continue;
    if (el.href) {
      const key = el.href.split("#")[0];
      if (seenHrefs.has(key)) continue;
      seenHrefs.add(key);
    }
    if (!el.clickable && !el.typeable && !el.selectable) continue;
    const id = `e${elements.length + 1}`;
    const label = el.text.slice(0, 60);
    const kind: "click" | "type" | "select" = el.typeable ? "type" : el.selectable ? "select" : "click";
    const hrefTail = el.href ? ` -> ${el.href.replace(/^https?:\/\//, "").slice(0, 70)}` : "";
    elements.push({
      id,
      attr: el.attr,
      kind,
      description:
        kind === "type"
          ? `${el.tag} "${label}" (type into this field)`
          : kind === "select"
            ? `${el.tag} "${label}" (dropdown; a follow-up picks the option)`
            : `${el.tag} "${label}"${hrefTail}`,
      options: kind === "select" ? (el.options ?? []) : undefined,
    });
  }
  return { elements, truncated: elements.length >= MAX_ELEMENTS };
}

function resolveGeneratorModel(): { model: Parameters<typeof generateText>[0]["model"]; label: string } | null {
  const providerEnv = process.env.JEV_BROWSER_TYPE_PROVIDER;
  const modelEnv = process.env.JEV_BROWSER_TYPE_MODEL;

  // An explicit OpenAI-compatible endpoint wins: Ollama, LM Studio, vLLM, proxies.
  const baseUrl = process.env.JEV_BROWSER_TYPE_BASE_URL;
  if (baseUrl) {
    const provider = createOpenAICompatible({
      name: "custom",
      baseURL: baseUrl,
      apiKey: process.env.JEV_BROWSER_TYPE_API_KEY ?? "",
    });
    return { model: provider(modelEnv ?? "gpt-5.6-luna"), label: "compatible-endpoint" };
  }

  const candidates: Array<{ provider: string; test: RegExp; make: (m: string) => any; defaultModel: string }> = [
    {
      provider: "openai",
      test: /^sk-/,
      make: (m) => createOpenAI({ apiKey: process.env.OPENAI_API_KEY! })(m),
      defaultModel: "gpt-5.6-luna",
    },
    {
      provider: "openrouter",
      test: /^sk-or-/,
      make: (m) =>
        createOpenAICompatible({
          name: "openrouter",
          baseURL: "https://openrouter.ai/api/v1",
          apiKey: process.env.OPENROUTER_API_KEY!,
        })(m),
      defaultModel: "google/gemini-2.5-flash-lite",
    },
    {
      provider: "anthropic",
      test: /^sk-ant-/,
      make: (m) => createAnthropic({ apiKey: process.env.ANTHROPIC_API_KEY! })(m),
      defaultModel: "claude-haiku-4.5",
    },
    {
      provider: "google",
      test: /^AIza/,
      make: (m) => createGoogleGenerativeAI({ apiKey: (process.env.GOOGLE_GENERATIVE_AI_API_KEY ?? process.env.GEMINI_API_KEY)! })(m),
      defaultModel: "gemini-2.5-flash",
    },
  ];

  // Explicit provider first, then auto-detection by key shape.
  const ordered = providerEnv
    ? [...candidates.filter((c) => c.provider === providerEnv), ...candidates.filter((c) => c.provider !== providerEnv)]
    : candidates;

  for (const candidate of ordered) {
    const key =
      candidate.provider === "openai"
        ? (process.env.OPENAI_API_KEY ?? "")
        : candidate.provider === "openrouter"
          ? (process.env.OPENROUTER_API_KEY ?? "")
          : candidate.provider === "anthropic"
            ? (process.env.ANTHROPIC_API_KEY ?? "")
            : (process.env.GOOGLE_GENERATIVE_AI_API_KEY ?? process.env.GEMINI_API_KEY ?? "");
    if (key.length > 20 && candidate.test.test(key)) {
      return { model: candidate.make(modelEnv ?? candidate.defaultModel), label: candidate.provider };
    }
  }
  return null;
}

